%======================================================================
\section{What is electric current?}

\subsection{Starting from everyday experience}
You already live inside electric circuits:
\begin{itemize}
  \item Flip a light switch and a lamp lights almost at once.
  \item A phone battery runs down after hours of use.
  \item A kettle heats water while connected to the mains.
\end{itemize}
In each case something is being \textbf{delivered} continuously --- not a one-off
spark like rubbing a balloon, but a steady flow. Physics names that flow
\textbf{electric current}.

\subsection{Current as flow of charge}
Charge is conserved and is carried by particles (electrons in metal wires).
If a net charge $\Delta Q$ passes a cross-section of a wire in time $\Delta t$,
the average current is
\[
I = \frac{\Delta Q}{\Delta t}.
\]
For steady current we write $I=Q/t$. The SI unit is the \textbf{ampere} (A):
\[
1\,\mathrm{A} = 1\,\mathrm{C\,s^{-1}}.
\]
So a current of $2\,\mathrm{A}$ means that $2$~coulombs of charge pass any chosen
point in the wire every second.

\begin{center}
\begin{tikzpicture}[scale=1.05]
  \draw[very thick] (-0.2,0) -- (6.2,0);
  \draw[very thick] (-0.2,1.1) -- (6.2,1.1);
  \foreach \x in {0.6,1.6,2.6,3.6,4.6,5.6} {
    \fill[negC] (\x,0.55) circle (2.4pt);
    \draw[-{Latex},thick,negC!70!black] (\x+0.15,0.55) -- (\x+0.55,0.55);
  }
  \draw[dashed] (3.1,-0.15) -- (3.1,1.25);
  \node[below,font=\small] at (3.1,-0.25) {cross-section};
  \node[font=\small] at (3.1,1.55) {$I=\Delta Q/\Delta t$ through this plane};
\end{tikzpicture}
\end{center}

\subsection{Conventional current vs electron flow}
In metals the mobile carriers are \textbf{electrons} (negative). They drift from
the negative terminal of a battery toward the positive terminal.

By historical convention, current arrows are drawn as the flow of
\textbf{positive} charge: from the battery's $+$ terminal, through the external
circuit, back to the $-$ terminal. That direction is called
\textbf{conventional current}. In a metal wire, electrons move the opposite way,
but circuit analysis uses conventional current unless a question explicitly asks
about electrons.

\begin{center}
\begin{tikzpicture}[scale=1.0]
  \draw[thick] (0,0) rectangle (1.1,0.55);
  \node[font=\scriptsize] at (0.55,0.28) {cell};
  \draw[thick] (1.1,0.28) -- (4.2,0.28) -- (4.2,1.6) -- (1.1,1.6) -- (1.1,0.28);
  \draw[thick] (0,0.28) -- (-0.5,0.28) -- (-0.5,1.6) -- (0,1.6);
  \node[font=\scriptsize] at (2.65,1.85) {external circuit};
  \draw[-{Latex},very thick,posC] (1.4,1.6) -- (3.9,1.6);
  \node[above,font=\scriptsize,posC] at (2.65,1.95) {conventional $I$};
  \draw[-{Latex},very thick,negC] (3.9,0.28) -- (1.4,0.28);
  \node[below,font=\scriptsize,negC] at (2.65,0.05) {electron drift};
\end{tikzpicture}
\end{center}

\begin{mdframed}[style=misbox]
\noindent\textbf{Common mistake --- ``current is used up''.}
Current is not consumed by a bulb the way petrol is burned.
In a series loop the same current leaves the battery and returns to it
(steady state). What the bulb ``uses'' is \textbf{energy} carried by the charge,
not the charge itself.
\end{mdframed}

\subsection{Why metals conduct}
In a metal lattice, outer electrons are delocalised --- the ``electron sea''.
An electric field inside the wire (set up by the battery) exerts a force on
those electrons, so they gain a small average \textbf{drift velocity} opposite
the field. Insulators have tightly bound electrons, so almost no free carriers
and essentially zero current under ordinary voltages.

Typical drift speeds in household wires are only millimetres per second, yet the
lamp lights immediately: the field (and the signal that a current should flow)
propagates along the circuit at a large fraction of the speed of light. The
electrons already present everywhere in the wire start drifting nearly at once.

\begin{mdframed}[style=tipbox]
\noindent\textbf{Order-of-magnitude check.}
$I=1\,\mathrm{A}$ for $1\,\mathrm{s}$ means $\Delta Q=1\,\mathrm{C}$.
Since $|e|=1.60\times 10^{-19}\,\mathrm{C}$, that is about
$6\times 10^{18}$ electrons --- huge numbers of tiny charges.
\end{mdframed}

%======================================================================
\section{Voltage, e.m.f.\ and potential difference}

\subsection{Energy per charge}
A battery does not create charge. It is a chemical \textbf{charge pump}: it
takes positive charge from the low-potential terminal and lifts it to the
high-potential terminal, doing work against the electrostatic field inside the
cell.

If the battery does work $W$ on charge $Q$, we define
\[
V = \frac{W}{Q}.
\]
The SI unit is the \textbf{volt}: $1\,\mathrm{V}=1\,\mathrm{J\,C^{-1}}$.
Saying ``a $1.5\,\mathrm{V}$ cell'' means each coulomb of charge that passes
through the cell gains about $1.5\,\mathrm{J}$ of electrical energy
(ideal case, no internal losses).

\subsection{E.m.f.\ vs potential difference}
\begin{itemize}
  \item \textbf{Electromotive force (e.m.f.)} $\mathcal{E}$ of a source is the
        energy given to each coulomb of charge that passes through the source
        (when the source is the only energy converter considered). Despite the
        name, e.m.f.\ is \emph{not} a force; it is measured in volts.
  \item \textbf{Potential difference (p.d.)} between two points is the energy
        converted from electrical form to another form (heat, light, \ldots)
        per coulomb as charge moves between those points.
\end{itemize}
Around a complete circuit, energy given by sources equals energy taken by
loads (and any internal heating of the source).

\begin{center}
\begin{tikzpicture}[scale=1.05]
  \draw[thick] (0,0.2) -- (0,1.4);
  \draw[very thick] (0.15,0.35) -- (0.15,1.25);
  \node[left,font=\scriptsize] at (-0.1,0.8) {$\mathcal{E}$};
  \draw[thick] (0.15,0.8) -- (3.2,0.8);
  \draw[thick] (3.2,0.35) rectangle (4.4,1.25);
  \node[font=\scriptsize] at (3.8,0.8) {$R$};
  \draw[thick] (4.4,0.8) -- (5.2,0.8) -- (5.2,0) -- (0.075,0) -- (0.075,0.2);
  \draw[-{Latex},thick] (1.2,0.95) -- (2.4,0.95);
  \node[above,font=\scriptsize] at (1.8,0.95) {$I$};
  \node[below,align=center,font=\small] at (2.6,-0.45)
    {Battery raises energy per coulomb; resistor converts it to heat};
\end{tikzpicture}
\end{center}

\begin{mdframed}[style=misbox]
\noindent\textbf{Common mistake --- voltage ``flows''.}
Voltage is not a flowing quantity. Current flows; voltage is a
\textbf{difference} in electrical PE per unit charge between two points.
Always ask: voltage \emph{across} which component?
\end{mdframed}

\subsection{Everyday scale}
\begin{itemize}
  \item AA cell: about $1.5\,\mathrm{V}$.
  \item USB charger: about $5\,\mathrm{V}$.
  \item Hong Kong mains: $220\,\mathrm{V}$ (a.c.\ r.m.s.\ --- later topic).
\end{itemize}
Larger voltage means more energy per coulomb, so a greater tendency to drive
current through a given resistance (and greater hazard).

