\section{Resistance and Ohm's law}

\subsection{What resistance means}
For a given potential difference, different components allow different currents.
\textbf{Resistance} quantifies how strongly a component opposes current:
\[
R = \frac{V}{I},\qquad [R]=\Omega=\mathrm{V\,A^{-1}}.
\]
A large $R$ means a small current for the same $V$.

\subsection{Ohm's law and ohmic conductors}
A conductor is \textbf{ohmic} if $V\propto I$ at constant temperature, so a
$V$--$I$ graph through the origin is a straight line. Then
\[
V = IR
\]
with constant $R$. Metals at fixed temperature are approximately ohmic.
Filament bulbs, diodes and many semiconductors are \textbf{non-ohmic}: $R$
changes with current or voltage (the graph is curved, or piecewise).

\begin{center}
\begin{tikzpicture}[x=0.55cm,y=0.45cm]
  \draw[-{Latex}] (0,0) -- (7.5,0) node[right,font=\scriptsize] {$V$};
  \draw[-{Latex}] (0,0) -- (0,7.2) node[above,font=\scriptsize] {$I$};
  \draw[thick,blue!55!black] (0,0) -- (6.2,5.5);
  \node[font=\scriptsize,blue!55!black] at (5.2,6.2) {ohmic};
  \begin{scope}[xshift=9.2cm]
    \draw[-{Latex}] (0,0) -- (7.5,0) node[right,font=\scriptsize] {$V$};
    \draw[-{Latex}] (0,0) -- (0,7.2) node[above,font=\scriptsize] {$I$};
    \draw[thick,red!60!black,domain=0:6.2,smooth,variable=\x]
      plot ({\x},{6.2*(1-exp(-0.45*\x))});
    \node[font=\scriptsize,red!60!black] at (4.8,6.3) {non-ohmic};
  \end{scope}
\end{tikzpicture}
\end{center}

\begin{mdframed}[style=misbox]
\noindent\textbf{Common mistake --- ``Ohm's law always holds''.}
$R=V/I$ can be computed at an operating point even for a non-ohmic device,
but that $R$ may not be constant. Ohm's law means the \emph{linear} relation
$V=IR$ with fixed $R$.
\end{mdframed}

\worked{2018}{23}{C}{69}{../2018_q23.png}{%
For $V<12\,\mathrm{V}$ the graph is a straight line through the origin, so the
conductor is ohmic there (A true). Beyond $12\,\mathrm{V}$ the slope increases
and $R=V/I$ falls, so resistance decreases (B true).
At $V=14\,\mathrm{V}$, $I=7\,\mathrm{A}$, so $R=14/7=2\,\Omega$ (D true).
At $I=5\,\mathrm{A}$ (on the steep segment) the voltage is about $13\,\mathrm{V}$,
so $R\approx 13/5=2.6\,\Omega$, not $0.5\,\Omega$.
(Option C confuses $V/I$ with the reciprocal of a local slope.)
$\Rightarrow$ \textbf{C} is incorrect.}

\subsection{Resistivity}
Resistance of a uniform wire depends on material and geometry:
\[
R = \rho\,\frac{\ell}{A},
\]
where $\ell$ is length, $A$ is cross-sectional area, and $\rho$ is
\textbf{resistivity} (unit $\Omega\,\mathrm{m}$). Longer wire $\Rightarrow$ larger $R$;
thicker wire $\Rightarrow$ smaller $R$.

\begin{center}
\begin{tikzpicture}[scale=1.15]
  \draw[thick] (0,0) -- (4.2,0) -- (4.6,0.55) -- (0.4,0.55) -- cycle;
  \draw[thick] (4.2,0) -- (4.2,0.35);
  \draw[thick] (4.6,0.55) -- (4.6,0.9) -- (0.4,0.9) -- (0.4,0.55);
  \draw[{Latex}-{Latex}] (0,-0.35) -- (4.2,-0.35) node[midway,below,font=\scriptsize] {$\ell$};
  \draw[{Latex}-{Latex}] (4.85,0) -- (4.85,0.9) node[midway,right,font=\scriptsize] {};
  \node[font=\scriptsize] at (5.35,0.45) {$A$};
  \node[font=\small] at (2.3,1.35) {$R=\rho\ell/A$};
\end{tikzpicture}
\end{center}

\worked{2021}{24}{A}{45}{../2021_q24.png}{%
For a cube of side $x$, length between opposite faces is $\ell=x$ and area is
$A=x^{2}$. Hence $R=\rho x/x^{2}=\rho/x$, so $R\propto 1/x$ $\Rightarrow$ \textbf{A}.}

\begin{mdframed}[style=tipbox]
\noindent\textbf{Exam habit.}
When a shape scales, rewrite $R=\rho\ell/A$ carefully. For a cube,
``thicker'' and ``longer'' both scale with $x$, so $R$ falls as $1/x$, not as $x$.
\end{mdframed}

%======================================================================
\section{Series and parallel networks}

\subsection{Series connection}
Components share one path: the \textbf{same current} $I$ through each.
Potential differences add:
\[
V = V_1+V_2+\cdots = I(R_1+R_2+\cdots).
\]
Equivalent resistance:
\[
R_{\mathrm{eq}} = R_1+R_2+\cdots.
\]
Series: adding a resistor always \textbf{increases} $R_{\mathrm{eq}}$.

\subsection{Parallel connection}
Components share the same two nodes: the \textbf{same p.d.}\ $V$ across each.
Currents add:
\[
I = I_1+I_2+\cdots = V\Bigl(\frac{1}{R_1}+\frac{1}{R_2}+\cdots\Bigr).
\]
Equivalent resistance:
\[
\frac{1}{R_{\mathrm{eq}}} = \frac{1}{R_1}+\frac{1}{R_2}+\cdots.
\]
For two resistors,
\[
R_{\mathrm{eq}} = \frac{R_1 R_2}{R_1+R_2}.
\]
Parallel: $R_{\mathrm{eq}}$ is \textbf{smaller} than the smallest branch resistance.

\begin{center}
\begin{tikzpicture}[scale=1.0]
  % series
  \draw[thick] (0,0.8) -- (0.6,0.8);
  \draw[thick] (0.6,0.55) rectangle (1.5,1.05);
  \node[font=\scriptsize] at (1.05,0.8) {$R_1$};
  \draw[thick] (1.5,0.8) -- (2.0,0.8);
  \draw[thick] (2.0,0.55) rectangle (2.9,1.05);
  \node[font=\scriptsize] at (2.45,0.8) {$R_2$};
  \draw[thick] (2.9,0.8) -- (3.5,0.8);
  \node[below,font=\small] at (1.75,0.2) {series: same $I$};
  % parallel
  \begin{scope}[xshift=5.2cm]
    \draw[thick] (0,0.8) -- (0.5,0.8) -- (0.5,1.4) -- (1.8,1.4);
    \draw[thick] (0.5,0.8) -- (0.5,0.2) -- (1.8,0.2);
    \draw[thick] (0.9,1.2) rectangle (1.6,1.6);
    \node[font=\scriptsize] at (1.25,1.4) {$R_1$};
    \draw[thick] (0.9,0.0) rectangle (1.6,0.4);
    \node[font=\scriptsize] at (1.25,0.2) {$R_2$};
    \draw[thick] (1.8,1.4) -- (1.8,0.2) -- (2.3,0.8) -- (1.8,0.8);
    \draw[thick] (1.8,0.8) -- (0.5,0.8);
    \node[below,font=\small] at (1.15,-0.35) {parallel: same $V$};
  \end{scope}
\end{tikzpicture}
\end{center}

\subsection{Current and voltage division}
\begin{itemize}
  \item \textbf{Series voltage divider:} $V_k = I R_k = V\dfrac{R_k}{R_1+R_2+\cdots}$.
        Larger resistance takes a larger share of the total p.d.
  \item \textbf{Parallel current divider:} $I_k = V/R_k$. Smaller resistance
        takes a larger share of the total current.
\end{itemize}

\subsection{Equipotential points and short circuits}
Points joined by ideal wire (zero resistance) are at the \textbf{same potential}.
A resistor connected between two equipotential points has zero p.d.\ across it
and carries no current --- it can be ignored for network reduction.
Closing a switch across a resistor \textbf{short-circuits} that resistor
(its terminals become equipotential).

\begin{mdframed}[style=misbox]
\noindent\textbf{Common mistake --- ``parallel always halves''.}
Two equal resistors $R$ in parallel give $R/2$. Unequal resistors do not.
Always use $1/R_{\mathrm{eq}}=\sum 1/R_i$, and never add resistances in parallel.
\end{mdframed}

\worked{2012}{26}{B}{58}{../2012_q26.png}{%
The top network reduces to some equivalent $R_{\mathrm{u}}$ in parallel with the
bottom $12\,\Omega$ resistor. Given $R_{ab}=6\,\Omega$:
\[
\frac{1}{6}=\frac{1}{R_{\mathrm{u}}}+\frac{1}{12}
\quad\Rightarrow\quad R_{\mathrm{u}}=12\,\Omega.
\]
Replace $12\,\Omega$ by $6\,\Omega$:
\[
\frac{1}{R'_{ab}}=\frac{1}{12}+\frac{1}{6}=\frac{1}{4}
\quad\Rightarrow\quad R'_{ab}=4\,\Omega.
\]
The unknown $R$ cancels --- we never need its value $\Rightarrow$ \textbf{B}.}

\worked{2013}{30}{B}{40}{../2013_q30.png}{%
Identical resistors: $Y\parallel Z$ gives $R/2$, then in series with $X$:
$R_{\mathrm{eq}}=R+R/2=\tfrac{3}{2}R$.
Total power $P=V^{2}/R_{\mathrm{eq}}=24\,\mathrm{W}$.
Voltage across the parallel pair is one-third of $V$ (series divider:
$R/2$ against $R$), so each of $Y,Z$ dissipates
$P_Z=(V/3)^{2}/R = V^{2}/(9R)$.
But $V^{2}/R = P\cdot R_{\mathrm{eq}}/R = 24\cdot\tfrac{3}{2}=36$,
hence $P_Z=36/9=4\,\mathrm{W}$ $\Rightarrow$ \textbf{B}.
(Shortcut: total current $I$ through $X$; half of $I$ through $Z$; powers scale
as $I^{2}R$, $\bigl(\tfrac{I}{2}\bigr)^{2}R$, $\bigl(\tfrac{I}{2}\bigr)^{2}R$
in ratio $4:1:1$, summing to $6$ parts $=24\,\mathrm{W}$, so each parallel
resistor gets $4\,\mathrm{W}$.)}

