\section{Kirchhoff ideas (conservation in circuits)}

\subsection{Kirchhoff's current law (KCL) --- charge conservation}
At any junction, charge cannot pile up in the steady state:
\[
\sum I_{\mathrm{in}} = \sum I_{\mathrm{out}}.
\]
Currents into a node equal currents out. This is why series elements share one
current and why parallel branch currents add.

\subsection{Kirchhoff's voltage law (KVL) --- energy conservation}
Around any closed loop, the signed sum of potential changes is zero:
\[
\sum \Delta V = 0.
\]
Climbing through a battery ($-$ to $+$) raises potential by $\mathcal{E}$
(ideal); passing through a resistor in the direction of conventional current
drops potential by $IR$.

\begin{center}
\begin{tikzpicture}[scale=1.05]
  \draw[thick] (0,0) rectangle (4.2,2.2);
  \draw[thick] (0.3,1.0) -- (0.3,0.35) -- (0.55,0.35);
  \draw[very thick] (0.55,0.15) -- (0.55,0.55);
  \draw[thick] (0.55,1.1) -- (0.55,1.85) -- (1.2,1.85);
  \draw[thick] (1.2,1.65) rectangle (2.2,2.05);
  \node[font=\scriptsize] at (1.7,1.85) {$R_1$};
  \draw[thick] (2.2,1.85) -- (3.5,1.85) -- (3.5,0.35) -- (2.2,0.35);
  \draw[thick] (1.2,0.15) rectangle (2.2,0.55);
  \node[font=\scriptsize] at (1.7,0.35) {$R_2$};
  \draw[thick] (1.2,0.35) -- (0.55,0.35);
  \node[font=\scriptsize] at (2.1,-0.35) {Loop: $\mathcal{E}-IR_1-IR_2=0$};
\end{tikzpicture}
\end{center}

\begin{mdframed}[style=tipbox]
\noindent\textbf{DSE use.}
You rarely need the full formal statement. You \emph{do} need the habits:
same $I$ in series; same $V$ in parallel; $\mathcal{E}=IR_{\mathrm{total}}$
for a single-loop ohmic circuit; energy/power accounting around the circuit.
\end{mdframed}

%======================================================================
\section{Internal resistance}

\subsection{Real batteries are not ideal}
A real cell has e.m.f.\ $\mathcal{E}$ and internal resistance $r$. When current
$I$ is drawn, some energy is dissipated inside the cell as heat. The
\textbf{terminal voltage} (p.d.\ across the external terminals) is
\[
V = \mathcal{E} - Ir
\]
(for a discharging cell). Equivalently
\[
\mathcal{E} = V + Ir = I(R+r)
\]
if the external load is a single equivalent resistance $R$.

\begin{center}
\begin{tikzpicture}[scale=1.1]
  \draw[thick] (0,0.7) -- (0.4,0.7);
  \draw[thick] (0.4,0.35) -- (0.4,1.05);
  \draw[very thick] (0.6,0.2) -- (0.6,1.2);
  \node[above,font=\scriptsize] at (0.5,1.25) {$\mathcal{E}$};
  \draw[thick] (0.6,0.7) -- (1.1,0.7);
  \draw[thick] (1.1,0.5) rectangle (1.9,0.9);
  \node[font=\scriptsize] at (1.5,0.7) {$r$};
  \draw[dashed] (-0.15,-0.1) rectangle (2.15,1.55);
  \node[font=\scriptsize] at (1.0,1.75) {cell};
  \draw[thick] (1.9,0.7) -- (3.2,0.7);
  \draw[thick] (3.2,0.45) rectangle (4.2,0.95);
  \node[font=\scriptsize] at (3.7,0.7) {$R$};
  \draw[thick] (4.2,0.7) -- (4.7,0.7) -- (4.7,0) -- (0,0) -- (0,0.7);
  \node[below,font=\small] at (2.3,-0.35)
    {$V_{\mathrm{terminal}}=\mathcal{E}-Ir$ across $R$};
\end{tikzpicture}
\end{center}

\subsection{Consequences}
\begin{itemize}
  \item Open circuit ($I=0$): $V=\mathcal{E}$ (voltmeter across terminals reads e.m.f.\
        if meter current is negligible).
  \item Larger load current $\Rightarrow$ larger $Ir$ drop $\Rightarrow$ smaller terminal $V$.
  \item Short circuit ($R\to 0$): $I\to\mathcal{E}/r$ (dangerous for low-$r$ cells).
\end{itemize}

\begin{mdframed}[style=misbox]
\noindent\textbf{Common mistake --- using $\mathcal{E}=IR$ with a real cell.}
$\mathcal{E}=I(R+r)$, not $IR$. Terminal voltage $V=IR$ equals $\mathcal{E}$ only
if $r=0$ or $I=0$.
\end{mdframed}

\worked{2012}{28}{B}{42}{../2012_q28.png}{%
External: $3\,\Omega\parallel 6\,\Omega$ gives $R=2\,\Omega$.
Total resistance $R+r=2+2=4\,\Omega$, so
$I_{\mathrm{total}}=\mathcal{E}/(R+r)=12/4=3\,\mathrm{A}$.
Terminal voltage $V=\mathcal{E}-Ir=12-3\cdot 2=6\,\mathrm{V}$.
Current in the $6\,\Omega$ branch: $I_6=V/6=1.0\,\mathrm{A}$ $\Rightarrow$ \textbf{B}.}

\worked{2014}{24}{C}{20}{../2014_q24.png}{%
When $S$ is closed the $3\,\Omega$ resistor is shorted, so external $R=6\,\Omega$
and $I=3.0\,\mathrm{A}$. Thus $\mathcal{E}=I(R+r)=3(6+r)=18+3r$.
When $S$ is open, external $R'=9\,\Omega$ and
$I'=\mathcal{E}/(9+r)=(18+3r)/(9+r)$.
For $r>0$, one finds $2.0\,\mathrm{A}<I'<3.0\,\mathrm{A}$.
Among the options only $2.4\,\mathrm{A}$ lies in that open interval
$\Rightarrow$ \textbf{C}.
(If someone wrongly assumes $r=0$, they get $I'=2.0\,\mathrm{A}$ and pick B ---
a common trap; facility only $20\%$.)}

%======================================================================
\section{Ammeters and voltmeters}

\subsection{Ideal meters}
\begin{itemize}
  \item Ideal \textbf{ammeter}: $R_A=0$, inserted \textbf{in series} with the
        element whose current is measured. It does not change the circuit current.
  \item Ideal \textbf{voltmeter}: $R_V=\infty$, connected \textbf{in parallel}
        with the element whose p.d.\ is measured. It draws no current.
\end{itemize}

\subsection{Practical meters}
A real ammeter has small but nonzero resistance, so inserting it slightly
\textbf{reduces} the current compared with the undisturbed circuit.
A real voltmeter has large but finite resistance, so connecting it slightly
\textbf{loads} the circuit and can change the p.d.\ being measured --- especially
across high-resistance components.

