\section{Formula summary}

\begin{center}
\begin{tabular}{@{}ll@{}}
\toprule
Idea & Formula / rule \\
\midrule
Current & $I=Q/t$ \\
p.d.\ / e.m.f. & $V=W/Q$,\quad $\mathcal{E}$ in volts \\
Ohm (ohmic) & $V=IR$ \\
Resistivity & $R=\rho\ell/A$ \\
Series & $R_{\mathrm{eq}}=R_1+R_2+\cdots$ (same $I$) \\
Parallel & $1/R_{\mathrm{eq}}=\sum 1/R_i$ (same $V$) \\
Internal resistance & $\mathcal{E}=I(R+r)=V+Ir$,\quad $V=\mathcal{E}-Ir$ \\
Power / energy & $P=VI=I^{2}R=V^{2}/R$,\quad $E=Pt$ \\
Meters & A in series (small $R_A$);\quad V in parallel (large $R_V$) \\
\bottomrule
\end{tabular}
\end{center}

